g0=[[0]*19 for _ in range(19)]
objs=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
for r,c,v in objs:
    g0[r][c]=v
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)): g0[r+dr][c+dc]=3
for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)): g0[10+dr][8+dc]=3
out=[row[:] for row in g0]
def draw(r,c,color,vertical):
    for dr,dc in (((-1,0),(1,0)) if vertical else ((0,-1),(0,1))):
        i,j=r+dr,c+dc
        while 0<=i<19 and 0<=j<19:
            # Pass through the source cross's own 3 arms, preserving them.
            if g0[i][j]!=0 and g0[i][j]!=3: break
            own_arm=(abs(i-r)+abs(j-c)==1 and g0[i][j]==3)
            if g0[i][j]==3 and not own_arm: break
            if g0[i][j]==0 and not (not vertical and j==8): out[i][j]=color
            i+=dr; j+=dc
for r,c,v in objs: draw(r,c,v,False)
for r,c,v in objs: draw(r,c,v,True)
print('\n'.join(' '.join(map(str,row)) for row in out))
